  "eventTitle": "發生第一次法難，平實導師開示「批月集」，辨正香港月溪法師之謬說",
  "eventDate": "1995",
  "summary": "第一次法難緣於法禪法師（自在居士）聲稱月溪法師所弘是究竟法，派遣該團體中的連老師滲入石牌共修會，鼓吹「一悟即成究竟佛地」邪見，致使劉、梁兩位同修退轉，臺南共修處亦因而關閉，後陸續有數位同修退轉，形成第一次法難。平實導師為救護諸同修，於1995年10月3日在中信局等處開始辨正月溪法師法義，宣說「批月集」。講完後隱其名諱整理成書，於1996年10月出版《正法眼藏—護法集》。2025年2月27日三版首刷之後，改為明舉月溪法師名號而作法義辨正，以免後世有人不明就理，又暢提月溪邪見。\n本書旨在闡明如何辨別真假開悟、悟後如何起修與斷除一念無明四住地煩惱等，此後月溪法師邪說漸漸消聲匿跡。由於平實導師著作法義勝妙，反襯諸方大師所悟不真，致使遭受抵制情形嚴重，初版時兩岸皆有大法師蒐集此書予以焚毀之事。",
