  "eventTitle": "發生第二次法難，平實導師撰寫《平實書箋》宣揚佛法第一義妙理",
  "eventDate": "1998",
  "summary": "正覺同修會1997年成立之後，平實導師堅持建立制度，重大事務悉由理監事會決議而行，掃除因人建事、廢事之弊端。然亦因此得罪心意有私之人，遂有元覽居士等人以不信佛性可以眼見而藉故生誹謗之心，欲推翻平實導師所說之法；林姓、劉姓親教師等十餘人受其影響聲言欲退出同修會，釀成第二次法難。\n平實導師藉著答覆元覽居士質難撰寫《平實書箋》，宣揚佛法第一義妙理，兼及定學修持及三界世俗諦；化惡緣為佛事，使佛子智慧更為深廣，轉能普益有情。",
