  "eventId": 10,
  "eventTitle": "平實導師首次講經，假臺北市石牌陽明精舍宣講《楞伽經》",
  "eventDate": "1995/08/11",
  "summary": "1995年8月11日平實導師應邀假陽明精舍開講《楞伽經》，1997年2月轉至正覺講堂續講，1997年9月26日宣講圓滿。此經為大乘佛法三部重要經典之一，禪宗見道者印證所悟真偽之根本經典，亦是悟後起修之義理依據，平實導師依自身實證手持經本直接宣講，開示佛法總成「五法、三自性」之核心要義及成就佛道之次第。\n平實導師後依開示之內容，重繕增補為《楞伽經詳解》(全套共十輯)，並於1999年5月陸續出版，自2000年5月《楞伽經詳解》第三輯起，平實導師直接於書中指名道姓破斥未悟示悟及方便示悟者之謬說（主要為印順法師及達賴喇嘛），藉以彰顯佛教正法之本義，導正被曲解之教義。復於2001年5月改版，並於2003年11月出版第十輯。目前此書已成為大陸很多佛學院之教材。",
