  "eventTitle": "平實導師於臺南侯氏宗祠演講「悟前與悟後—大乘的無我觀」",
  "eventDate": "1999/11/14",
  "summary": "平實導師應臺南紡織公司侯董事長之邀參觀臺南侯氏宗祠，期間以「悟前與悟後—大乘的無我觀」為題演講並即席問答，分別從悟前與悟後宣說大乘佛法之無我觀，解說二乘所證解脫道與大乘佛菩提道之異同。\n平實導師演講內容及當日問答經整理後於2002年9月出版《大乘無我觀》。",
