  "summary": "原臺南共修處借與法蓮師使用，因其於第三次法難退轉，故本會另立直屬本會之臺南共修處。平實導師在臺南新講堂安座法會後，以「真如、如來藏、阿賴耶識間之關係」為內涵，開示「真開悟」與「假開悟」之差別，乃是為退轉於阿賴耶識正法者所作之法義辨正。\n平實導師演講內容彙集成書，2004年6月出版《真假開悟》。",
