  "summary": "本書是繼《入不二門》之後第二本公案拈提集錦，選錄平實導師所造公案拈提十七則結集成書，免費結緣流通，冀能挽救更多佛光山四眾弟子，亦藉此令久學佛弟子遠離邪見，增益大乘般若見道之緣。\n此書取名《普門自在》，係因如來藏妙法乃是普門自在之勝法，於一切眾生家宅之中，普門皆具，故說如來藏是「普門自在」之絕妙好心。",
