  "summary": "2003年第三次法難之時，學員對會內種種事務及弘法事宜多有不能理解之處，復因部分利益學員之法義亦應適時宣說，令學員皆得其利，因而於2003年7月31日首次出刊《正覺電子報》，2003年10月開始發行書面版本，免費贈閱，廣利大眾。\n《正覺電子報》初以刊登聯繫學員情誼為主的小品，輔以轉載網站文章，後轉型為連載平實導師、親教師文章之重要平台。",
