  "summary": "平實導師親撰《阿含正義—唯識學探源》共七輯，彰顯四阿含諸經中隱說之大乘八識具足法義、大乘佛教在佛世就存在，破斥印順、昭慧等人誣指大乘經典是部派佛教以後佛弟子們創造。《阿含正義》七輯出版之後，少有人敢公然主張大乘非佛說。\n2011年10月，四川大學出版社出版簡體字版《阿含概論》，由七輯《阿含正義》精簡而成。",
