  "eventDate": "2007/11/01",
  "summary": "平實導師所著《鈍鳥與靈龜》，舉證天童宏智與大慧宗杲兩位禪師所悟同屬如來藏妙心，辨正藍吉富先生所寫文章違背歷史事實。\n本書與《童女迦葉考》皆駁斥聖嚴法師及其弟子於學術界所造之種種謬論，最終解決長久以來的空有之諍。\n《鈍鳥與靈龜》英譯本於2023年7月11日出版。",
