  "eventTitle": "平實導師開講《維摩詰所說不可思議解脫經》",
  "eventDate": "2004/11/09",
  "summary": "2004年11月9日平實導師開講《維摩詰所說不可思議解脫經》。平實導師以道種智的深妙智慧詳實解釋經中密意，令維摩詰大士所說深妙正法得以正確宣流於人間，利益當代及後世學人。自古本經即為禪門之照妖鏡，凡所悟若不能與此經意旨相符，即是錯悟。\n宣講圓滿後出版《維摩詰經講記》全套共六輯。於2007年11月30日出版第一輯，2008年9月30日出版第六輯。2013年10月出版《維摩詰經講記》簡體中文版共三輯。",
