  "eventId": 97,
  "eventTitle": "《正覺學報》創刊",
  "eventDate": "2007/12/02",
  "summary": "鑑於釋昭慧要求從學術觀點評論釋印順，促使本會蔡禮政老師向法鼓山所屬之《中華佛學研究所》期刊投稿〈《阿含經》對存有之定義〉一文，舉證經文證實如來藏常住且可實證；但該期刊卻根據印順一派無因唯緣論謬說而予無理封殺。為爭取八識論正法在佛學學術界的發言權，本會正式創辦《正覺學報》，以導正遭印順學派長期掌控的佛學學術界。為配合《正覺學報》出版，於2008年2月建置正覺學報網站。\n平實導師在《正覺學報》創刊號首次提出「實證佛教」一詞，強調佛法實證的重要性。學報發行五期後停刊。",
