  "eventTitle": "出版蔡正禮老師著《現代人應有之宗教觀》口袋書",
  "eventDate": "2007/01",
  "summary": "新竹講堂成立伊始，有學員提出現代人修學佛法基本教理問題，本會蔡正禮老師擇要答覆，並整理印行《現代人應有之宗教觀》一書流通。後有一貫道點傳師以網路化名質疑此書，蔡正禮老師遂以問答形式撰文回覆，再版時增補於書後。\n之後，本會持續出版親教師所著之口袋書，透過簡潔扼要形式，協助讀者快速掌握佛法精義。包括：\n2007年12月《確保您的權益—器官捐贈應注意自我保護》\n2009年5月《平實導師之真實義》\n2009年8月《一貫道與開悟》\n2011年3月《繫念思惟念佛法門》\n2015年8月《從一佛所在世界談宇宙大覺者》\n2019年5月《佛教與成佛》\n2024年3月《尊師重道》\n2025年1月《正覺總持咒的威德力》\n2025年10月《老了要靠誰？》\n2026年3月《無字真經》\n2026年3月《為什麼要學佛？》",
