  "eventDate": "1999/01",
  "summary": "平實導師親授之臺中禪淨新班設置有「般若信箱」，課前解答學員提問。之後臺北講堂每週二講經延續「般若信箱」作法，平實導師於講經前先回答學員們提問，幫助大眾建立「法與次法」的正確知見。\n隨著2003年本會發生第三次法難，行之多年的「般若信箱」當場回答提問方式，並未能攝受心中有疑的退轉者，遂取消平實導師週二講經前的問答時間，將「般若信箱」移至2003年7月創刊的正覺電子報，至2009年7月改為不定期刊出，後將正覺電子報「般若信箱」問答內容，分類彙整成書發行。2007年2月出版《遠惑趣道》第一輯，2009年12月出版《遠惑趣道》第二輯。",
