  "note": "",
  "eventId": 115,
  "eventTitle": "出版《意識虛妄經教彙編》",
  "eventDate": "2010/04/01",
  "summary": "本書彙編北傳《阿含經》及南傳《尼柯耶》經文，旨在證明意識虛妄，令學人斷除「意識真實有」之我見，從而有緣證悟大乘般若。此書特別選在2010年4月25日高雄巨蛋「穿越時空──超意識」萬人演講前夕出版，作為大會一萬多份結緣紀念品中的核心書籍之一，為當天演講主題提供堅實經教基礎。",
  "matchBy": "書名相同"
