  "eventTitle": "平實導師開講《金剛般若波羅蜜經》",
  "eventDate": "2006/12/12",
  "summary": "《金剛般若波羅蜜經》為中國大乘佛法家喻戶曉的般若經典，旨在揭示第八識金剛心。平實導師採宗通方式開演此經，詳解真實義理，拈提與經文有關的禪宗公案。演說內容有事、有理，更有宗門密意，幫助聞法者實證《金剛經》般若智慧，轉入內門廣修六度萬行。\n《金剛經宗通》全套共九輯，依平實導師宣講《金剛經》內容整理出版。2012年5月31日出版第一輯，2013年9月30日出版第九輯。",
