  "eventTitle": "開始出版《淺談達賴喇嘛之雙身法》等多本破密書籍",
  "eventDate": "2008/06",
  "summary": "2008年起，本會彙整史實與外媒報導，出版多部破斥西藏密宗雙身法本質的書籍，呼籲社會大眾應遠離邪法，期能維護台灣社會純正風氣。歷年出版著作分類臚列如下：\n一、論邪教領袖達賴喇嘛\n2008年6月《淺談達賴喇嘛之雙身法—兼論解讀《密續》之達文西密碼》，至今已印行66萬冊。2012年2月《末代達賴—性交教主的悲歌》\n2012年10月《黯淡的達賴—失去光彩的諾貝爾和平獎》\n2014年8月《恭祝達賴喇嘛八十大壽》\n二、論假藏傳佛教\n2008年9月《密宗真相》（原名：《魔界轉世》）\n\n2011年7月《喇嘛性世界—揭開藏傳佛教譚崔瑜伽的面紗》\n2011年7月《俺矇你把你哄——六字大明咒揭密》\n2011年11月《假藏傳佛教的神話—性、謊言、喇嘛教》\n2015年1月《西藏「活佛轉世」制度——附佛、造神、世俗法》\n三、破邪顯正之報導\n2016年3月《老去人間萬事休，應須洗心從佛祖》\n2016年10月《您不可不知的事實》",
