  "summary": "本會郭正益老師所著《甘願做菩薩》，闡述菩薩真實義及修心理趣。「菩薩」就是心量廣大，壞事自向己，好事予他人，依止如來藏服務假我的體性，轉而服務一切有情。佛弟子欲圓滿佛菩提道，須從「甘願」作一位真正的菩薩開始，堅固菩薩作意，方能日漸成為無私無我的菩薩。\n本書廣受大眾歡迎，迄今結緣印行已逾十九萬冊。",
