  "eventDate": "2008/03",
  "summary": "《甘露法門》口袋書摘錄自平實導師著《甘露法雨、宗通與說通》等。之後本會摘錄平實導師著作中的勝妙法，刊行多本口袋書免費結緣流通，協助讀者快速掌握佛法精義；此作法為白正偉老師所發起。書摘作品包括：\n2008年3月《成佛之道》\n2008年5月《如何修證解脫道》\n2008年7月《淨土奇特行門﹝往生極樂世界﹞》\n2009年7月《觀行斷三縛結》\n2009年7月《如來藏中藏如來》\n2009年11月《出家菩薩首重虛心求教勤求證悟》\n2014年10月《證道歌略釋》\n2016年7月《表相歸依與實義歸依》",
