  "eventId": 109,
  "eventTitle": "平實導師開講《妙法蓮華經》，揭示一乘究竟成佛秘旨",
  "eventDate": "2009/07/21",
  "summary": "《妙法蓮華經》是圓教經典，顯示十方諸佛的真實本質，圓滿收攝一切法教。此經所說法義深妙，世人難解，平實導師直抒佛陀本懷，將各品蘊含之密意，如實顯示於當代學人眼前，並揭示唯一佛乘至理，最後以〈法華大義〉而總其成，依佛旨圓攝於如來藏妙心。\n宣講圓滿後出版《法華經講義》全套共廿五輯。2015年5月31日出版第一輯，2019年5月31日出版第二十五輯。",
