  "eventId": 160,
  "eventTitle": "出版張善思居士著《次法—實證佛法前應有的條件》",
  "eventDate": "2017/06/30",
  "summary": "本會張善思居士所著《次法—實證佛法前應有的條件》，以佛陀在《阿含經》中教導的次法「施論、戒論、生天之論，欲為不淨、上漏為患、出要為上」為架構，闡述實踐次法是眾生的福德基礎，更是佛法實證所需的必要條件。本書之出版期能救護諸方於次法無真修實證之法師居士能免於大妄語業誤導眾生。\n本書2017年6月及8月出版上下兩冊。",
