  "summary": "本會趙玲子老師應馬來西亞「智行學會」邀請，於2023年2月25日、26日舉辦兩場「佛法與中華文化系列講座」，主講《三乘菩提概說》及《我與無我》。演講內容後刊載於馬國首相安華先生之著作並發行給海外華人閱讀之《亞洲文藝復興》一書，這是正法於東南亞推廣且落實於文字之始舉。\n本會後於2023年4月在馬來西亞成立共修中心，6月10日正式開始共修，以觀看弘法視頻及心得分享為主。",
