  "summary": "2017年12月19日平實導師開講《大法鼓經》，詳解世尊宣演此經之因緣及真實義理，開顯「信大方廣」的菩薩功德，詳釋「非法亦法，法亦非法」之真諦，深入說明「大法鼓」之義，以及正法住世的最後80餘年，月光菩薩為諸眾生再擊大法鼓的種種因緣。2019年1月22日宣演圓滿後出版《大法鼓經講義》全套共六輯。於2023年1月30日出版第一輯，2023年11月30日出版第六輯。",
