  "eventTitle": "平實導師開講《不退轉法輪經》",
  "eventDate": "2019/02/12",
  "summary": "2019年2月12日平實導師開演《不退轉法輪經》。此經是大乘般若期前的通教經典，平實導師詳解此經，讓聽聞者能解「釋迦牟尼」即能仁寂靜的第八識真如之深義，聽聞「此經」及「釋迦牟尼佛」聖名已，未來當得不退轉於大乘法輪。鑑於正覺同修會曾發生三次法難，平實導師不願再有任何人退轉，是故特意宣說此經。\n2021年3月23日宣講圓滿後出版《不退轉法輪經講義》全套共十輯。2024年1月30日出版第一輯，2025年7月30日出版第十輯。",
