  "eventTitle": "舉辦「玄奘文化系列講座」，揭開《成唯識論釋》新書發表會暨佛法大業論壇序幕",
  "eventDate": "2022/05/15",
  "summary": "本會自2022年5月15日起陸續在臺灣臺北、宜蘭、臺中、臺南等八處舉辦「玄奘文化系列講座」，介紹玄奘大師生平、佛法正義、歷史文化等，每場講座內容包括影片欣賞、親民講座、座談交流。第九場於2023年5月28日在臺北市舉辦平實導師《成唯識論釋》新書發表會暨佛法大業論壇。\n第十場於2025年3月2日在高雄市立圖書館舉辦平實導師《成唯識論釋》第二、第三輯新書發表會暨佛法大業論壇。",
