  "eventId": 192,
  "eventTitle": "出版《誰是師子身中蟲》",
  "eventDate": "2024/05/30",
  "summary": "本書集結平實導師2020年至2024年於正覺同修會會員大會之開示，直指部派佛教聲聞凡夫僧正是佛所說的「師子身中蟲」，彼等寄生在佛教正法中，對三乘菩提似懂非懂，講出大量相似佛法擾亂正見弘傳，反來誣指「大乘非佛說」。今日釋印順所率領的學術界及密宗皆其遺緒。\n本書以結緣方式放置各地寺廟流通廣宣，讓出家眾藉以認清釋印順就是師子身中蟲。",
