  "eventDate": "2021/03/30",
  "summary": "《解深密經》是世尊晚年第三轉法輪時，宣說佛陀自內所證之境智行果及「諸法唯識」最極甚深祕密妙義之經典。2021年3月30日平實導師重講此經，令證悟明心者明解大乘法道之成佛次第、悟後進修一切種智之內涵，亦令諸方未悟者據此經中佛語正義，修正邪見，速能入道。後整理出版《解深密經講義》共十二輯。2025年9月30日出版第一輯，○年○月○日出版第十二輯。",
