  "eventId": 42,
  "eventTitle": "出版《宗通與說通》，闡明成佛之道要義",
  "eventDate": "2000/12",
  "summary": "平實導師於《宗通與說通》書中主張全面性的佛教修證，不應分宗立派，更不應像印順法師一樣割裂佛法，使佛法分崩離析。本書以宗門實證與教門義理讓大眾得以認識成佛之道次第，確立「唯識」為悟後起修之增上慧學，奠定後續出版《邪見與佛法》基礎。附錄收錄〈正覺發願文〉。",
